fn nodeBase(d:usize,i:usize)usize{return 2+d+i*(d+2);}
fn validTree(v:[*]const i64,d:usize,n:usize,i:i64,seen:*[15]bool,reached:*usize)bool{if(i<0)return true;const j:usize=@intCast(i);if(j>=n or seen[j])return false;seen[j]=true;reached.*+=1;const b=nodeBase(d,j);const l=v[b+d];const r=v[b+d+1];if(l>=0 and l==r)return false;return validTree(v,d,n,l,seen,reached) and validTree(v,d,n,r,seen,reached);}
fn searchTree(v:[*]const i64,d:usize,i:i64,depth:usize,q:[3]i64,best:*[3]i64,bestd:*i64,visited:*i64)void{if(i<0)return;visited.*+=1;const b=nodeBase(d,@intCast(i));var dist:i64=0;for(0..d)|k|{const delta=q[k]-v[b+k];dist+=delta*delta;}if(dist<bestd.*){bestd.*=dist;for(0..d)|k|{best[k]=v[b+k];}}const axis=depth%d;const l=v[b+d];const r=v[b+d+1];const near=if(q[axis]<=v[b+axis])l else r;const far=if(q[axis]<=v[b+axis])r else l;searchTree(v,d,near,depth+1,q,best,bestd,visited);const split=q[axis]-v[b+axis];if(split*split<bestd.*)searchTree(v,d,far,depth+1,q,best,bestd,visited);}
fn putI64(outp:[*]u8,offset:usize,x:i64)void{const bits=@as(u64,@bitCast(x));for(0..8)|k|{outp[offset+k]=@truncate(bits>>(8*k));}}
export fn nearest_neighbour_search(v:[*]const i64,n:usize,outp:[*]u8,cap:usize)i64{if(n<5)return -1;const d0=v[0];const n0=v[1];if((d0!=2 and d0!=3)or n0<1 or n0>15)return -1;const d:usize=@intCast(d0);const count:usize=@intCast(n0);if(n!=2+d+count*(d+2))return -1;var q=[_]i64{0}**3;var best=[_]i64{0}**3;for(0..d)|k|{q[k]=v[2+k];if(q[k] < -1000 or q[k]>1000)return -1;}for(0..count)|i|{const b=nodeBase(d,i);for(0..d)|k|{if(v[b+k] < -1000 or v[b+k]>1000)return -1;}const l=v[b+d];const r=v[b+d+1];if(l < -1 or l>=n0 or r < -1 or r>=n0 or (l>=0 and l==r))return -1;}var seen=[_]bool{false}**15;var reached:usize=0;if(!validTree(v,d,count,0,&seen,&reached)or reached!=count)return -1;var bestd:i64=9223372036854775807;var visited:i64=0;searchTree(v,d,0,0,q,&best,&bestd,&visited);if(cap<48)return -2;var result=[_]i64{d0,best[0],best[1],0,bestd,visited};if(d==3)result[3]=best[2];for(0..6)|k|{putI64(outp,k*8,result[k]);}return 48;}
